    "/* \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80"" Event log \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80"" */\n"
    "#logCard { min-height: 170px; }\n"
    "\n"
    "#log {\n"
    "  list-style: none;\n"
    "  font-size: .8rem;\n"
    "  font-family: 'Cascadia Code', 'Fira Code', monospace;\n"
    "  color: var(--text-dim);\n"
    "  max-height: 170px;\n"
    "  overflow-y: auto;\n"
    "  display: flex;\n"
    "  flex-direction: column;\n"
    "  gap: .12rem;\n"
    "}\n"
    "#log li { padding: .08rem 0; }\n"
    "#log li:first-child { color: var(--text); }\n"
    "\n"
    "/* \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80"" IP configuration dialog \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80"" */\n"
    "dialog {\n"
    "  border: 1px solid var(--border);\n"
    "  border-radius: var(--radius);\n"
    "  background: var(--surface);\n"
    "  color: var(--text);\n"
    "  box-shadow: var(--shadow);\n"
    "  padding: 0;\n"
    "  width: min(94vw, 420px);\n"
    "  max-height: 92vh;\n"
    "}\n"
    "dialog::backdrop { background: rgba(0,0,0,.66); }\n"
    "\n"
    "dialog form {\n"
    "  padding: 1.4rem 1.5rem;\n"
    "  display: flex;\n"
    "  flex-direction: column;\n"
    "  gap: .85rem;\n"
    "  overflow-y: auto;\n"
    "  max-height: 92vh;\n"
    "}\n"
    "\n"
    "dialog h3 {\n"
    "  font-size: 1rem;\n"
    "  color: var(--accent);\n"
    "  border-bottom: 1px solid var(--border);\n"
    "  padding-bottom: .55rem;\n"
    "}\n"
    "\n"
    ".modes {\n"
    "  border: 1px solid var(--border);\n"
    "  border-radius: 8px;\n"
    "  padding: .6rem .8rem;\n"
    "  display: flex;\n"
    "  gap: 1.4rem;\n"
    "  font-size: .87rem;\n"
    "}\n"
    ".modes legend { font-size: .72rem; color: var(--text-dim); text-transform: uppercase; letter-spacing: .06em; padding: 0 .3rem; }\n"
    ".modes label { display: flex; align-items: center; gap: .4rem; cursor: pointer; }\n"
    "\n"
    ".field { display: flex; flex-direction: column; gap: .3rem; font-size: .8rem; }\n"
    ".field span { color: var(--text-dim); }\n"
    "\n"
    ".field input {\n"
    "  font: inherit;\n"
    "  font-size: .9rem;\n"
    "  font-family: 'Cascadia Code', 'Fira Code', monospace;\n"
    "  padding: .45rem .6rem;\n"
    "  border-radius: 7px;\n"
    "  border: 1px solid var(--border);\n"
    "  background: var(--bg);\n"
    "  color: var(--text);\n"
    "}\n"
    ".field input:focus { outline: none; border-color: var(--accent2); }\n"
    ".field input:disabled { opacity: .45; }\n"
    "\n"
    "#staticFields { display: flex; flex-direction: column; gap: .85rem; }\n"
    "\n"
    ".hint { font-size: .74rem; color: var(--text-dim); line-height: 1.45; }\n"
    "\n"
    ".msg {\n"
    "  font-size: .8rem;\n"
    "  border-radius: 8px;\n"
    "  padding: .45rem .65rem;\n"
    "  border: 1px solid transparent;\n"
    "}\n"
    ".msg.ok  { color: var(--accent); border-color: var(--accent); background: rgba(88,214,141,.1); }\n"
    ".msg.err { color: #f1948a;      border-color: var(--danger); background: rgba(231,76,60,.1); }\n"
    "\n"
    ".actions {\n"
    "  display: flex;\n"
    "  flex-wrap: wrap;\n"
    "  gap: .6rem;\n"
    "  padding-top: .3rem;\n"
    "  border-top: 1px solid var(--border);\n"
    "}\n"
    ".actions .btn-ghost { margin-left: auto; }\n"
    "\n"
    "/* \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80"" Scrollbar \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80"" */\n"
    "::-webkit-scrollbar       { width: 6px; }\n"
    "::-webkit-scrollbar-track { background: transparent; }\n"
    "::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }\n"
    "</style>\n"
    "</head>\n"
    "<body>\n"
    "  <header>\n"
    "    <div class=\"logo\">\n"
    "      <svg viewBox=\"0 0 32 32\" width=\"30\" height=\"30\" fill=\"none\" aria-hidden=\"true\">\n"
    "        <circle cx=\"16\" cy=\"16\" r=\"13\" stroke=\"#58d68d\" stroke-width=\"2.5\"/>\n"
    "        <circle cx=\"16\" cy=\"16\" r=\"4\" fill=\"#58d68d\"/>\n"
    "        <line x1=\"16\" y1=\"3\"  x2=\"16\" y2=\"9\"  stroke=\"#58d68d\" stroke-width=\"2\"/>\n"
    "        <line x1=\"16\" y1=\"23\" x2=\"16\" y2=\"29\" stroke=\"#58d68d\" stroke-width=\"2\"/>\n"
    "        <line x1=\"3\"  y1=\"16\" x2=\"9\"  y2=\"16\" stroke=\"#58d68d\" stroke-width=\"2\"/>\n"
    "        <line x1=\"23\" y1=\"16\" x2=\"29\" y2=\"16\" stroke=\"#58d68d\" stroke-width=\"2\"/>\n"
    "      </svg>\n"
    "      <span id=\"hdrName\">UNO R4 Monitor</span>\n"
    "    </div>\n"
    "    <div class=\"hdr-right\">\n"
    "      <button class=\"btn btn-ghost\" id=\"cfgOpen\" type=\"button\">IP configuration</button>\n"
    "      <div class=\"status-dot\" id=\"connDot\" title=\"Live connection\"></div>\n"
    "    </div>\n"
    "  </header>\n"
    "\n"
    "  <main>\n"
    "\n"
    "    <!-- Encoder -->\n"
    "    <section class=\"card\" id=\"encCard\">\n"
    "      <h2>Encoder</h2>\n"
    "      <div class=\"big-value\"><span id=\"countVal\">0</span></div>\n"
    "      <div class=\"sub\">counts &middot; A2 / D3, button A3</div>\n"
    "      <button class=\"btn btn-primary\" id=\"resetBtn\" type=\"button\">Reset count</button>\n"
    "    </section>\n"
    "\n"
    "    <!-- Temperature -->\n"
    "    <section class=\"card\" id=\"tempCard\">\n"
    "      <h2>Temperature</h2>\n"
    "      <div class=\"gauge-wrap\">\n"
    "        <svg class=\"gauge\" viewBox=\"0 0 200 120\" aria-hidden=\"true\">\n"
    "          <path d=\"M 20 110 A 90 90 0 0 1 180 110\" fill=\"none\"\n"
    "                stroke=\"#2c3e50\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n"
    "          <path id=\"gaugeArc\" d=\"M 20 110 A 90 90 0 0 1 180 110\" fill=\"none\"\n"
    "                stroke=\"#58d68d\" stroke-width=\"16\" stroke-linecap=\"round\"\n"
    "                stroke-dasharray=\"283\" stroke-dashoffset=\"283\"/>\n"
    "          <text x=\"14\"  y=\"128\" class=\"tick\">&#8722;20</text>\n"
    "          <text x=\"86\"  y=\"24\"  class=\"tick\">40</text>\n"
    "          <text x=\"170\" y=\"128\" class=\"tick\">100</text>\n"
    "        </svg>\n"
    "        <div class=\"gauge-value\"><span id=\"tempVal\">--.--</span>&#176;C</div>\n"
    "      </div>\n"
    "      <div class=\"sub\" id=\"tempLabel\">Waiting for DS18B20&hellip;</div>\n"
    "    </section>\n"
    "\n"
    "    <!-- Network -->\n"
    "    <section class=\"card\" id=\"netCard\">\n"
    "      <h2>Network</h2>\n"
    "      <dl class=\"kv\">\n"
    "        <dt>System name</dt><dd id=\"netName\">&mdash;</dd>\n"
    "        <dt>IP address</dt><dd id=\"netIp\">&mdash;</dd>\n"
    "        <dt>Mode</dt><dd id=\"netMode\">&mdash;</dd>\n"
    "        <dt>Link</dt><dd id=\"netLink\">&mdash;</dd>\n"
    "      </dl>\n"
    "      <div class=\"warn hidden\" id=\"dirtyWarn\">Unsaved configuration changes.</div>\n"
    "    </section>\n"
    "\n"
    "    <!-- Log -->\n"
    "    <section class=\"card wide\" id=\"logCard\">\n"
    "      <h2>Event log</h2>\n"
    "      <ol id=\"log\"></ol>\n"
    "    </section>\n"
    "\n"
    "  </main>\n"
    "\n"
    "  <!-- IP configuration popup -->\n"
    "  <dialog id=\"cfgDialog\">\n"
    "    <form id=\"cfgForm\" method=\"dialog\">\n"
    "      <h3>IP configuration</h3>\n"
    "\n"
    "      <fieldset class=\"modes\">\n"
    "        <legend>Addressing</legend>\n"
    "        <label><input type=\"radio\" name=\"mode\" value=\"static\" id=\"modeStatic\"/> Static IP</label>\n"
    "        <label><input type=\"radio\" name=\"mode\" value=\"dhcp\"   id=\"modeDhcp\"/> DHCP</label>\n"
    "      </fieldset>\n"
    "\n"
    "      <label class=\"field\">\n"
    "        <span>System name</span>\n"
    "        <input type=\"text\" id=\"fName\" maxlength=\"23\" autocomplete=\"off\"\n"
    "               placeholder=\"ALS-lab\" pattern=\"[A-Za-z0-9_-]{1,23}\"/>\n"
    "      </label>\n"
    "\n"
    "      <div id=\"staticFields\">\n"
    "        <label class=\"field\">\n"
    "          <span>IP address</span>\n"
    "          <input type=\"text\" id=\"fIp\" autocomplete=\"off\" placeholder=\"192.168.1.10\"/>\n"
    "        </label>\n"
    "        <label class=\"field\">\n"
    "          <span>Subnet mask</span>\n"
    "          <input type=\"text\" id=\"fSn\" autocomplete=\"off\" placeholder=\"255.255.255.0\"/>\n"
    "        </label>\n"
    "        <label class=\"field\">\n"
    "          <span>Gateway</span>\n"
    "          <input type=\"text\" id=\"fGw\" autocomplete=\"off\" placeholder=\"192.168.1.1\"/>\n"
    "        </label>\n"
    "        <label class=\"field\">\n"
    "          <span>DNS server</span>\n"
    "          <input type=\"text\" id=\"fDns\" autocomplete=\"off\" placeholder=\"192.168.1.1\"/>\n"
    "        </label>\n"
    "      </div>\n"
    "\n"
    "      <label class=\"field\">\n"
    "        <span>MAC address</span>\n"
    "        <input type=\"text\" id=\"fMac\" autocomplete=\"off\" placeholder=\"DE:AD:BE:EF:FE:10\"/>\n"
    "      </label>\n"
    "\n"
    "      <p class=\"hint\" id=\"cfgHint\">\n"
    "        Saving writes to the on-chip EEPROM. Network changes take effect after a reboot.\n"
    "        The system name is shown on the LCD, here and on the telnet console.\n"
    "      </p>\n"
    "      <p class=\"msg hidden\" id=\"cfgMsg\"></p>\n"
    "\n"
    "      <div class=\"actions\">\n"
    "        <button class=\"btn btn-primary\" id=\"cfgSave\"   type=\"button\">Save to EEPROM</button>\n"
    "        <button class=\"btn btn-danger\"  id=\"cfgReboot\" type=\"button\">Reboot system</button>\n"
    "        <button class=\"btn btn-ghost\"   id=\"cfgClose\"  type=\"button\">Close</button>\n"
    "      </div>\n"
    "    </form>\n"
    "  </dialog>\n"
    "\n"
    "  <script>\n"
    "// \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\n"
    "// UNO R4 Minima monitor - SSE client, encoder reset and IP configuration popup\n"
    "// \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\n"
    "\n"
    "'use strict';\n"
    "\n"
    "const $ = (id) => document.getElementById(id);\n"
    "\n"
    "// \xe2""\x94""\x80""\xe2""\x94""\x80"" DOM refs \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\n"
    "const connDot   = $('connDot');\n"
    "const hdrName   = $('hdrName');\n"
    "\n"
    "const countVal  = $('countVal');\n"
    "const resetBtn  = $('resetBtn');\n"
    "\n"
    "const tempVal   = $('tempVal');\n"
    "const tempLabel = $('tempLabel');\n"
    "const gaugeArc  = $('gaugeArc');\n"
    "\n"
    "const netName   = $('netName');\n"
    "const netIp     = $('netIp');\n"
    "const netMode   = $('netMode');\n"
    "const netLink   = $('netLink');\n"
    "const dirtyWarn = $('dirtyWarn');\n"
    "\n"
    "const log       = $('log');\n"
    "\n"
    "const cfgDialog = $('cfgDialog');\n"
    "const cfgOpen   = $('cfgOpen');\n"
    "const cfgSave   = $('cfgSave');\n"
    "const cfgReboot = $('cfgReboot');\n"
    "const cfgClose  = $('cfgClose');\n"
    "const cfgMsg    = $('cfgMsg');\n"
    "\n"
    "const modeStatic   = $('modeStatic');\n"
    "const modeDhcp     = $('modeDhcp');\n"
    "const staticFields = $('staticFields');\n"
    "const fName = $('fName'), fIp = $('fIp'), fSn = $('fSn');\n"
    "const fGw   = $('fGw'),   fDns = $('fDns'), fMac = $('fMac');\n"
    "\n"
    "// \xe2""\x94""\x80""\xe2""\x94""\x80"" Constants \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\n"
    "const TEMP_MIN   = -20;\n"
    "const TEMP_MAX   = 100;\n"
    "const ARC_LENGTH = 283;      // half-circle length in the gauge's SVG units\n"
    "const MAX_LOG    = 40;\n"
    "\n"
    "// The board pushes its state at least every SSE_HEARTBEAT_MS (5 s). If nothing\n"
    "// arrives for this long the stream is dead even though the socket still looks\n"
    "// open, so reconnect. This is the only way to notice a reboot: the W5500 is\n"
    "// reset without closing its TCP connections, the browser's socket is left\n"
    "// half-open, and onerror never fires.\n"
    "const WATCHDOG_MS = 15000;\n"
    "const RETRY_MS    = 3000;\n"
    "\n"
    "// \xe2""\x94""\x80""\xe2""\x94""\x80"" Event log \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\n"
    "function logEvent(msg) {\n"
    "  const li = document.createElement('li');\n"
    "  li.textContent = '[' + new Date().toLocaleTimeString() + '] ' + msg;\n"
    "  log.prepend(li);\n"
    "  while (log.children.length > MAX_LOG) log.removeChild(log.lastChild);\n"
    "}\n"
    "\n"
    "// \xe2""\x94""\x80""\xe2""\x94""\x80"" Rendering \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\n"
    "\n"
    "function renderTemp(t, ok) {\n"
    "  if (!ok || t === null || t === undefined || isNaN(t)) {\n"
    "    tempVal.textContent   = '--.--';\n"
    "    tempVal.style.color   = '';\n"
    "    tempLabel.textContent = 'No sensor detected';\n"
    "    gaugeArc.style.strokeDashoffset = ARC_LENGTH;\n"
    "    return;\n"
    "  }\n"
    "\n"
    "  tempVal.textContent = t.toFixed(2);\n"
    "\n"
    "  let colour, label;\n"
    "  if      (t < 0)  { colour = '#3498db'; label = 'Freezing'; }\n"
    "  else if (t < 15) { colour = '#58d68d'; label = 'Cold'; }\n"
    "  else if (t < 25) { colour = '#f4d03f'; label = 'Comfortable'; }\n"
    "  else if (t < 35) { colour = '#f39c12'; label = 'Warm'; }\n"
    "  else             { colour = '#e74c3c'; label = 'Hot'; }\n"
    "\n"
    "  tempVal.style.color   = colour;\n"
    "  gaugeArc.style.stroke = colour;\n"
    "  tempLabel.textContent = label + ' \xc2""\xb7"" 12-bit resolution';\n"
    "\n"
    "  const pct = Math.min(1, Math.max(0, (t - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)));\n"
    "  gaugeArc.style.strokeDashoffset = ARC_LENGTH * (1 - pct);\n"
    "}\n"
    "\n"
    "// Previous values, so the log only records real transitions.\n"
    "let prev = { temp: undefined, tempOk: undefined, count: undefined,\n"
    "             ip: undefined, link: undefined, name: undefined };\n"
    "\n"
    "function applyState(s) {\n"
    "  if (s.count !== undefined && s.count !== prev.count) {\n"
    "    countVal.textContent = s.count;\n"
    "    if (prev.count !== undefined) logEvent('Encoder count: ' + s.count);\n"
    "    prev.count = s.count;\n"
    "  }\n"
    "\n"
    "  if (s.temp !== undefined && (s.temp !== prev.temp || s.tempOk !== prev.tempOk)) {\n"
    "    renderTemp(s.temp, s.tempOk);\n"
    "    if (prev.temp !== undefined && s.tempOk) {\n"
    "      logEvent('Temperature: ' + s.temp.toFixed(2) + ' \xc2""\xb0""C');\n"
    "    } else if (prev.tempOk && !s.tempOk) {\n"
    "      logEvent('Temperature sensor lost');\n"
    "    }\n"
    "    prev.temp   = s.temp;\n"
    "    prev.tempOk = s.tempOk;\n"
    "  }\n"
    "\n"
    "  if (s.name !== undefined && s.name !== prev.name) {\n"
    "    hdrName.textContent = s.name;\n"
    "    netName.textContent = s.name;\n"
    "    document.title      = s.name + ' monitor';\n"
    "    prev.name = s.name;\n"
    "  }\n"
    "\n"
    "  if (s.ip !== undefined && s.ip !== prev.ip) {\n"
    "    netIp.textContent = s.ip;\n"
    "    prev.ip = s.ip;\n"
    "  }\n"
    "\n"
    "  if (s.dhcp !== undefined) {\n"
    "    netMode.textContent = s.dhcp\n"
    "      ? ('DHCP' + (s.bound ? '' : ' (no lease)'))\n"
    "      : 'Static';\n"
    "  }\n"
    "\n"
    "  if (s.link !== undefined && s.link !== prev.link) {\n"
    "    netLink.textContent = s.link ? 'up' : 'down';\n"
    "    if (prev.link !== undefined) logEvent('Ethernet link ' + (s.link ? 'up' : 'down'));\n"
    "    prev.link = s.link;\n"
    "  }\n"
    "\n"
    "  if (s.dirty !== undefined) dirtyWarn.classList.toggle('hidden', !s.dirty);\n"
    "}\n"
    "\n"
    "// \xe2""\x94""\x80""\xe2""\x94""\x80"" SSE connection \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\n"
    "\n"
    "let evtSource      = null;\n"
    "let reconnectTimer = null;\n"
    "let watchdogTimer  = null;\n"
    "let lastMsgAt      = 0;\n"
    "let everConnected  = false;\n"
    "\n"
    "function setDot(state) {          // 'connected' | 'error' | ''\n"
    "  connDot.className = 'status-dot' + (state ? ' ' + state : '');\n"
    "  connDot.title = state === 'connected' ? 'Receiving live data'\n"
    "                : state === 'error'     ? 'No data \xe2""\x80""\x93"" reconnecting'\n"
    "                : 'Connecting\xe2""\x80""\xa6""';\n"
    "}\n"
    "\n"
    "function scheduleReconnect(why) {\n"
    "  setDot('error');\n"
    "  logEvent(why + ' \xe2""\x80""\x93"" retrying in ' + (RETRY_MS / 1000) + ' s');\n"
    "  if (evtSource) { evtSource.close(); evtSource = null; }\n"
    "  clearTimeout(reconnectTimer);\n"
    "  reconnectTimer = setTimeout(connectSSE, RETRY_MS);\n"
    "}\n"
    "\n"
    "function connectSSE() {\n"
    "  if (evtSource) { evtSource.close(); evtSource = null; }\n"
    "  clearTimeout(reconnectTimer);\n"
    "\n"
    "  setDot('');\n"
    "  evtSource = new EventSource('/events');\n"
    "  // Treat the stream as silent until real data lands: onopen only proves the\n"
    "  // socket opened, not that the board behind it is alive.\n"
    "  lastMsgAt = Date.now();\n"
    "\n"
    "  evtSource.onopen = () => {\n"
    "    logEvent(everConnected ? 'Reconnected' : 'Live connection established');\n"
    "    everConnected = true;\n"
    "    lastMsgAt = Date.now();\n"
    "  };\n"
    "\n"
    "  evtSource.onmessage = (e) => {\n"
    "    lastMsgAt = Date.now();\n"
    "    setDot('connected');           // the dot means \"data is flowing\"\n"
    "    try { applyState(JSON.parse(e.data)); }\n"
    "    catch (err) { console.warn('SSE parse error:', err); }\n"
    "  };\n"
    "\n"
    "  evtSource.onerror = () => scheduleReconnect('Connection lost');\n"
    "\n"
    "  // One watchdog for the life of the page, not one per connection.\n"
    "  if (!watchdogTimer) {\n"
    "    watchdogTimer = setInterval(() => {\n"
    "      if (!evtSource) return;                       // a retry is already queued\n"
    "      if (Date.now() - lastMsgAt < WATCHDOG_MS) return;\n"
    "      scheduleReconnect('No data for ' + (WATCHDOG_MS / 1000) + ' s');\n"
    "    }, 1000);\n"
    "  }\n"
    "}\n"
    "\n"
    "// \xe2""\x94""\x80""\xe2""\x94""\x80"" Encoder reset \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\n"
    "\n"
    "resetBtn.addEventListener('click', async () => {\n"
    "  resetBtn.disabled = true;\n"
    "  try {\n"
    "    const r = await fetch('/api/reset', { method: 'POST' });\n"
    "    if (!r.ok) throw new Error('HTTP ' + r.status);\n"
    "    logEvent('Encoder count reset');\n"
    "  } catch (err) {\n"
    "    logEvent('ERROR resetting count: ' + err.message);\n"
    "  } finally {\n"
    "    resetBtn.disabled = false;\n"
    "  }\n"
    "});\n"
    "\n"
    "// \xe2""\x94""\x80""\xe2""\x94""\x80"" IP configuration popup \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\n"
    "\n"
    "function showMsg(text, ok) {\n"
    "  cfgMsg.textContent = text;\n"
    "  cfgMsg.className   = 'msg ' + (ok ? 'ok' : 'err');\n"
    "}\n"
    "\n"
    "function clearMsg() {\n"
    "  cfgMsg.textContent = '';\n"
    "  cfgMsg.className   = 'msg hidden';\n"
    "}\n"
    "\n"
    "function syncModeFields() {\n"
    "  // The static address fields are meaningless while DHCP is selected.\n"
    "  const dhcp = modeDhcp.checked;\n"
    "  [fIp, fSn, fGw, fDns].forEach((el) => { el.disabled = dhcp; });\n"
    "  staticFields.style.opacity = dhcp ? '.5' : '1';\n"
    "}\n"
    "\n"
    "modeStatic.addEventListener('change', syncModeFields);\n"
    "modeDhcp.addEventListener('change', syncModeFields);\n"
    "\n"
    "cfgOpen.addEventListener('click', async () => {\n"
    "  clearMsg();\n"
    "  try {\n"
    "    const r = await fetch('/api/netcfg');\n"
    "    if (!r.ok) throw new Error('HTTP ' + r.status);\n"
    "    const c = await r.json();\n"
    "\n"
    "    modeDhcp.checked   = !!c.dhcp;\n"
    "    modeStatic.checked = !c.dhcp;\n"
    "    fName.value = c.name || '';\n"
    "    fIp.value   = c.ip   || '';\n"
    "    fSn.value   = c.sn   || '';\n"
    "    fGw.value   = c.gw   || '';\n"
    "    fDns.value  = c.dns  || '';\n"
    "    fMac.value  = c.mac  || '';\n"
    "    syncModeFields();\n"
    "\n"
    "    if (c.jumper) {\n"
    "      showMsg('The defaults jumper was grounded at boot, so the stored settings ' +\n"
    "              'were ignored for this session. Saving still works.', false);\n"
    "    } else if (c.dirty) {\n"
    "      showMsg('There are staged changes that are not in EEPROM yet.', false);\n"
    "    }\n"
    "  } catch (err) {\n"
    "    showMsg('Could not read the configuration: ' + err.message, false);\n"
    "  }\n"
    "  cfgDialog.showModal();\n"
    "});\n"
    "\n"
    "cfgClose.addEventListener('click', () => cfgDialog.close());\n"
    "\n"
    "cfgSave.addEventListener('click', async () => {\n"
    "  clearMsg();\n"
    "  cfgSave.disabled = true;\n"
    "\n"
    "  // Stage the form, then commit \xe2""\x80""\x94"" the same two steps the telnet console uses.\n"
    "  const params = new URLSearchParams();\n"
    "  params.set('dhcp', modeDhcp.checked ? '1' : '0');\n"
    "  params.set('name', fName.value.trim());\n"
    "  params.set('mac',  fMac.value.trim());\n"
    "  if (!modeDhcp.checked) {\n"
    "    params.set('ip',  fIp.value.trim());\n"
    "    params.set('sn',  fSn.value.trim());\n"
    "    params.set('gw',  fGw.value.trim());\n"
    "    params.set('dns', fDns.value.trim());\n"
    "  }\n"
    "\n"
    "  try {\n"
    "    const stage = await (await fetch('/api/netcfg?' + params.toString(),\n"
    "                                     { method: 'POST' })).json();\n"
    "    if (!stage.ok) { showMsg(stage.msg || 'Rejected', false); return; }\n"
    "\n"
    "    const saved = await (await fetch('/api/save', { method: 'POST' })).json();\n"
    "    if (!saved.ok) { showMsg(saved.msg || 'EEPROM write failed', false); return; }\n"
    "\n"
    "    showMsg('Saved to EEPROM. Reboot to apply the network settings.', true);\n"
    "    logEvent('Configuration saved to EEPROM');\n"
    "  } catch (err) {\n"
    "    showMsg('Request failed: ' + err.message, false);\n"
    "  } finally {\n"
    "    cfgSave.disabled = false;\n"
    "  }\n"
    "});\n"
    "\n"
    "cfgReboot.addEventListener('click', async () => {\n"
    "  if (!confirm('Reboot the board now? Any unsaved changes are lost.')) return;\n"
    "  clearMsg();\n"
    "  cfgReboot.disabled = true;\n"
    "  try {\n"
    "    await fetch('/api/reboot', { method: 'POST' });\n"
    "    showMsg('Rebooting \xe2""\x80""\x93"" this page will reconnect automatically.', true);\n"
    "    logEvent('Reboot requested');\n"
    "  } catch (err) {\n"
    "    // A reset can cut the connection before the response arrives; that is\n"
    "    // the expected outcome, not a failure.\n"
    "    showMsg('Reboot requested.', true);\n"
    "  } finally {\n"
    "    setTimeout(() => { cfgReboot.disabled = false; }, 3000);\n"
    "  }\n"
    "});\n"
    "\n"
    "// \xe2""\x94""\x80""\xe2""\x94""\x80"" Boot \xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\xe2""\x94""\x80""\n"
    "\n"
    "renderTemp(null, false);\n"
    "syncModeFields();\n"
    "logEvent('Dashboard loaded');\n"
    "connectSSE();\n"
    "\n"
    "// Browsers throttle timers in background tabs, so a hidden page can sit on a\n"
    "// dead stream. Re-check as soon as it comes back to the foreground.\n"
    "document.addEventListener('visibilitychange', () => {\n"
    "  if (document.visibilityState !== 'visible') return;\n"
    "  if (evtSource && Date.now() - lastMsgAt < WATCHDOG_MS) return;\n"
    "  scheduleReconnect('Tab resumed with a stale stream');\n"
    "});\n"
    "</script>\n"
    "</body>\n"
    "</html>\n"
;
const size_t WEB_INDEX_HTML_LEN = sizeof(WEB_INDEX_HTML) - 1;

